"""B-rep collision scan for the exported and re-imported candidate."""

from __future__ import annotations

import itertools
import math
import sys
import time
from pathlib import Path
from typing import Callable

import cadquery as cq
from OCP.BRepAlgoAPI import BRepAlgoAPI_Common

from build_all_xl430 import REFERENCE_XL430, TARGETS, component_name
from common import (
    EXPECTED_LEAVES,
    FOLLOWER_SOURCE,
    LENGTH_TOLERANCE_MM,
    REFERENCE_DIR,
    VOLUME_TOLERANCE_MM3,
    read_json,
)

sys.path.insert(0, str(FOLLOWER_SOURCE))

from assembly_io import bounds, read_step  # noqa: E402

MOTOR_PATHS = frozenset(
    [REFERENCE_XL430, "/Robot Arm v14/XL-430_new v1:2"]
    + [path for _, path, _ in TARGETS]
)


def original_unit(path: str) -> str:
    matches = [motor for motor in MOTOR_PATHS if path.startswith(f"{motor}/")]
    if len(matches) > 1:
        raise ValueError("Ambiguous physical motor occurrence")
    return matches[0] if matches else path


def trusted_membership() -> dict[str, str]:
    """Derive unit membership from the source STEP, never from a report flag."""
    _, _, original = read_step(REFERENCE_DIR / "arm.step")
    reference_leaves = [
        row for row in original if row.path.startswith(f"{REFERENCE_XL430}/")
    ]
    if len(original) != 161 or len(reference_leaves) != 35:
        raise ValueError("Reference structure changed")
    target_paths = [path for _, path, _ in TARGETS]
    result = {}
    for row in original:
        if any(row.path.startswith(f"{target}/") for target in target_paths):
            continue
        result[component_name(f"KEEP_{row.index:03d}_{row.name}")] = original_unit(
            row.path
        )
    for tag, target, _ in TARGETS:
        for index, leaf in enumerate(reference_leaves):
            result[component_name(f"{tag}_XL430_{index:02d}_{leaf.name}")] = target
    if len(result) != EXPECTED_LEAVES:
        raise ValueError("Physical-unit membership is incomplete")
    return result


def bbox_overlaps(left: list[float], right: list[float]) -> bool:
    return all(
        min(left[index + 3], right[index + 3])
        - max(left[index], right[index])
        > LENGTH_TOLERANCE_MM
        for index in range(3)
    )


def common_volume(left: cq.Shape, right: cq.Shape) -> tuple[float, cq.Shape]:
    operation = BRepAlgoAPI_Common(left.wrapped, right.wrapped)
    operation.Build()
    if not operation.IsDone():
        raise RuntimeError("BRepAlgoAPI_Common did not complete")
    raw = operation.Shape()
    if raw.IsNull():
        raise RuntimeError("Boolean result is null, not a verified empty intersection")
    common = cq.Shape.cast(raw)
    if not common.isValid():
        raise RuntimeError("Boolean returned an invalid shape")
    volumes = [float(solid.Volume()) for solid in common.Solids()]
    if any(
        not math.isfinite(volume) or volume < -VOLUME_TOLERANCE_MM3
        for volume in volumes
    ):
        raise RuntimeError("Boolean returned invalid solid volume")
    return float(sum(volumes)), common


def scan(run: Path, progress: Callable[[str], None] = print) -> dict:
    start = time.monotonic()
    membership = trusted_membership()
    _, _, rows = read_step(run / "CAD/arm_all_XL430_static_UNACCEPTED.step")
    names = [row.name for row in rows]
    if len(names) != len(set(names)) or set(names) != set(membership):
        raise ValueError("Re-imported occurrence identities differ from source structure")
    manifest = read_json(run / "replacement_manifest.json")
    if (
        not isinstance(manifest, list)
        or len(manifest) != EXPECTED_LEAVES
        or {item["name"] for item in manifest} != set(names)
    ):
        raise ValueError("Candidate manifest does not cover the re-imported STEP")

    errors = []
    non_solid_names = []
    solids = {}
    boxes = {}
    for row in rows:
        try:
            shape = row.world
            if not shape.isValid():
                raise ValueError("Invalid B-rep occurrence")
            if not shape.Solids():
                non_solid_names.append(row.name)
                if membership[row.name] not in MOTOR_PATHS:
                    raise ValueError("External structural part is not a solid")
                continue
            volume = float(sum(solid.Volume() for solid in shape.Solids()))
            if not math.isfinite(volume) or volume <= 0:
                raise ValueError("Invalid solid volume")
            solids[row.name] = shape
            boxes[row.name] = bounds(shape)
        except Exception as error:  # CAD kernel errors must become blocking evidence.
            errors.append({"occurrence": row.name, "error": str(error)})

    pairs = [
        (left, right)
        for left, right in itertools.combinations(solids, 2)
        if bbox_overlaps(boxes[left], boxes[right])
    ]
    progress(
        f"B-rep scan: {len(rows)} leaves, {len(solids)} solid occurrences, "
        f"{len(pairs)} candidate pairs"
    )
    external = []
    internal = []
    for number, (left, right) in enumerate(pairs, 1):
        try:
            volume, common = common_volume(solids[left], solids[right])
            if volume > VOLUME_TOLERANCE_MM3:
                left_unit = membership[left]
                right_unit = membership[right]
                item = {
                    "left": left,
                    "right": right,
                    "left_unit": left_unit,
                    "right_unit": right_unit,
                    "volume_mm3": volume,
                    "bounds_mm": bounds(common),
                }
                supplier_internal = (
                    left_unit == right_unit and left_unit in MOTOR_PATHS
                )
                (internal if supplier_internal else external).append(item)
        except Exception as error:  # A failed pair is not equivalent to no collision.
            errors.append({"left": left, "right": right, "error": str(error)})
        if number % 50 == 0:
            progress(
                f"Checked {number}/{len(pairs)}; external overlaps={len(external)}"
            )
    return {
        "check_kind": "static_exported_BREP_not_full_motion",
        "complete": not errors,
        "errors": errors,
        "leaf_count": len(rows),
        "valid_brep_occurrences": len(rows) - len(errors),
        "solid_occurrences": len(solids),
        "non_solid_reference_occurrences": len(non_solid_names),
        "non_solid_reference_names": non_solid_names,
        "total_solid_pairs": len(solids) * (len(solids) - 1) // 2,
        "boolean_candidate_pairs": len(pairs),
        "boolean_attempted_pairs": len(pairs),
        "external_collision_count": len(external),
        "external_collisions": external,
        "supplier_internal_collision_count": len(internal),
        "supplier_internal_collisions": internal,
        "motor_occurrence_count": len(
            {value for value in membership.values() if value in MOTOR_PATHS}
        ),
        "volume_tolerance_mm3": VOLUME_TOLERANCE_MM3,
        "bbox_length_tolerance_mm": LENGTH_TOLERANCE_MM,
        "elapsed_seconds": round(time.monotonic() - start, 3),
    }

"""Rebuild, validate, and fail closed before print packaging."""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

from common import (
    OUTPUT_ROOT,
    PART_NAMES,
    candidate_inventory,
    read_json,
    study_run,
    write_json,
)
from print_gate import assert_fresh_destination, evaluate


def run_worker(operation: str, run_id: str) -> None:
    command = [
        sys.executable,
        "-X",
        "faulthandler",
        "-u",
        str(Path(__file__).with_name("cad_worker.py")),
        operation,
        "--run-id",
        run_id,
    ]
    try:
        result = subprocess.run(command, timeout=600, check=False)
    except subprocess.TimeoutExpired as error:
        raise RuntimeError(f"CAD {operation} timed out; print is blocked") from error
    if result.returncode != 0:
        raise RuntimeError(
            f"CAD {operation} exited with code {result.returncode}; print is blocked"
        )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    subcommands = parser.add_subparsers(dest="command", required=True)
    for name in ("rebuild", "validate", "print-package"):
        command = subcommands.add_parser(name)
        command.add_argument("--run-id", default="current")
        if name == "print-package":
            command.add_argument("--output", type=Path, required=True)
    args = parser.parse_args(argv)
    run = None
    try:
        run = study_run(args.run_id)
        if args.command == "print-package":
            assert_fresh_destination(
                args.output, quarantine=OUTPUT_ROOT / "unaccepted"
            )
        if args.command == "rebuild":
            run_worker("generate", args.run_id)
        # Never trust an archived JSON when deciding whether packaging may run.
        run_worker("validate", args.run_id)
        report = read_json(run / "reports/validation.json")
        reasons = evaluate(report, candidate_inventory(run))
        if reasons:
            print(
                json.dumps(
                    {
                        "status": "unaccepted",
                        "print_status": "blocked",
                        "external_collision_count": report["static_interference"][
                            "external_collision_count"
                        ],
                        "supplier_internal_collision_count": report[
                            "static_interference"
                        ]["supplier_internal_collision_count"],
                        "reasons": reasons,
                    },
                    ensure_ascii=False,
                    indent=2,
                )
            )
            return 2
        if args.command == "print-package":
            destination = args.output.resolve()
            destination.parent.mkdir(parents=True, exist_ok=True)
            descriptor, temporary = tempfile.mkstemp(
                dir=destination.parent, suffix=".zip"
            )
            os.close(descriptor)
            try:
                with zipfile.ZipFile(
                    temporary, "w", compression=zipfile.ZIP_DEFLATED
                ) as archive:
                    for name in PART_NAMES:
                        for extension in ("step", "stl"):
                            path = run / f"CAD/parts/{name}.{extension}"
                            archive.write(path, f"parts/{path.name}")
                    archive.writestr(
                        "validation.json",
                        json.dumps(report, ensure_ascii=False, indent=2),
                    )
                if candidate_inventory(run) != report["candidate_sha256"]:
                    raise ValueError("Candidate changed during packaging")
                os.link(temporary, destination)
            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)
        return 0
    except Exception as error:
        message = {
            "status": "blocked_validation_error",
            "print_status": "blocked",
            "error_type": type(error).__name__,
            "error": str(error),
        }
        if run is not None and run.is_dir():
            write_json(run / "reports/last_failure.json", message)
            write_json(run / "reports/print_gate.json", message)
        print(json.dumps(message, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3


if __name__ == "__main__":
    raise SystemExit(main())

"""Fail-closed gate between diagnostic CAD and any print packaging."""

from __future__ import annotations

import math
from pathlib import Path
from typing import Any

from common import (
    EXPECTED_LEAVES,
    PART_NAMES,
    PENDING_CHECKS,
    STUDY_ID,
    VOLUME_TOLERANCE_MM3,
)


def evaluate(report: Any, current_inventory: dict[str, str]) -> list[str]:
    if not isinstance(report, dict):
        return ["missing_or_malformed_validation_report"]
    reasons = []
    if report.get("study_id") != STUDY_ID:
        reasons.append("wrong_study_or_baseline_report")
    if report.get("candidate_sha256") != current_inventory or not current_inventory:
        reasons.append("stale_or_missing_candidate_hashes")
    if report.get("acceptance_state") != "accepted_for_print":
        reasons.append("candidate_is_unaccepted")
    static = report.get("static_interference")
    if not isinstance(static, dict):
        reasons.append("missing_static_collision_check")
    else:
        if static.get("complete") is not True or static.get("errors") != []:
            reasons.append("collision_check_incomplete_or_failed")
        count = static.get("external_collision_count")
        hits = static.get("external_collisions")
        if (
            type(count) is not int
            or count < 0
            or not isinstance(hits, list)
            or count != len(hits)
        ):
            reasons.append("invalid_collision_count_or_missing_pair_evidence")
        elif count != 0:
            reasons.append(f"external_collisions_remaining:{count}")
        if (
            static.get("leaf_count") != EXPECTED_LEAVES
            or static.get("motor_occurrence_count") != 6
        ):
            reasons.append("unexpected_assembly_structure")
        attempted = static.get("boolean_attempted_pairs")
        candidates = static.get("boolean_candidate_pairs")
        if (
            type(attempted) is not int
            or type(candidates) is not int
            or attempted != candidates
            or attempted < 0
        ):
            reasons.append("not_all_candidates_checked")
        tolerance = static.get("volume_tolerance_mm3")
        if (
            type(tolerance) not in (float, int)
            or not math.isfinite(tolerance)
            or tolerance != VOLUME_TOLERANCE_MM3
        ):
            reasons.append("changed_or_missing_collision_tolerance")
    parts = report.get("parts")
    if not isinstance(parts, dict) or set(parts) != set(PART_NAMES):
        reasons.append("missing_part_validation")
    else:
        for name, item in parts.items():
            if (
                not isinstance(item, dict)
                or item.get("valid_brep") is not True
                or item.get("solid_count") != 1
                or item.get("stl_watertight") is not True
                or item.get("stl_positive_volume") is not True
            ):
                reasons.append(f"invalid_part_geometry:{name}")
            if not isinstance(item, dict) or item.get("all_xl430_compatible") is not True:
                reasons.append(f"all_xl430_part_fit_unverified:{name}")
    checks = report.get("required_checks", {})
    if not isinstance(checks, dict):
        checks = {}
    for name in PENDING_CHECKS:
        check = checks.get(name)
        if (
            not isinstance(check, dict)
            or check.get("status") != "passed"
            or check.get("candidate_sha256") != current_inventory
            or not check.get("evidence")
        ):
            reasons.append(f"missing_same_revision_evidence:{name}")
    return reasons


def assert_fresh_destination(path: Path, quarantine: Path) -> None:
    if path.exists() or path.is_symlink():
        raise FileExistsError("Print destination already exists; nothing was replaced")
    if path.resolve().is_relative_to(quarantine.resolve()):
        raise ValueError("A print package cannot be placed inside diagnostic CAD")

"""Generate the rigid all-XL430 replacement as an unaccepted candidate."""

from __future__ import annotations

import argparse
import sys
from dataclasses import dataclass
from pathlib import Path

import cadquery as cq
from OCP.IFSelect import IFSelect_RetDone
from OCP.STEPCAFControl import STEPCAFControl_Reader
from OCP.TCollection import TCollection_ExtendedString
from OCP.TDataStd import TDataStd_Name
from OCP.TDF import TDF_Label, TDF_LabelSequence
from OCP.TDocStd import TDocStd_Document
from OCP.XCAFDoc import XCAFDoc_DocumentTool

from common import (
    EXPECTED_LEAVES,
    FOLLOWER_SOURCE,
    PART_NAMES,
    REFERENCE_DIR,
    STUDY_ID,
    check_reference_hashes,
    write_json,
)

sys.path.insert(0, str(FOLLOWER_SOURCE))

from mesh_export import export_closed_stl  # noqa: E402
from rebuild import build_geometry, require_single_solid  # noqa: E402

REFERENCE_XL430 = "/Robot Arm v14/XL-430_new v1:1"
EXISTING_XL430 = (
    "/Robot Arm v14/XL-430_new v1:1",
    "/Robot Arm v14/XL-430_new v1:2",
)
TARGETS = (
    ("J3", "/Robot Arm v14/XL,XC-330 v1:6", ("distal", "wrist")),
    ("J4", "/Robot Arm v14/XL,XC-330 v1:7", ("distal",)),
    (
        "J5_GRIPPER",
        "/Robot Arm v14/gripper v9:1/XL,XC-330 v1:1",
        ("distal", "wrist", "gripper"),
    ),
    ("J6", "/Robot Arm v14/XL,XC-330 v1:8", ("distal",)),
)


@dataclass
class Prototype:
    assembly: cq.Assembly
    manifest: list[dict]
    baseline: object


def _label_name(label: TDF_Label) -> str:
    attribute = TDataStd_Name()
    if label.FindAttribute(TDataStd_Name.GetID_s(), attribute):
        return attribute.Get().ToExtString()
    return "unnamed"


def read_assembly_nodes(path: Path) -> dict[str, cq.Location]:
    reader = STEPCAFControl_Reader()
    reader.SetNameMode(True)
    if reader.ReadFile(str(path)) != IFSelect_RetDone:
        raise ValueError(f"Cannot read {path}")
    document = TDocStd_Document(TCollection_ExtendedString("assembly-nodes"))
    if not reader.Transfer(document):
        raise ValueError(f"Cannot transfer {path}")
    shape_tool = XCAFDoc_DocumentTool.ShapeTool_s(document.Main())
    nodes: dict[str, cq.Location] = {}

    def walk(label: TDF_Label, location: cq.Location, parent: str) -> None:
        name = _label_name(label)
        if shape_tool.IsReference_s(label):
            location = location * cq.Location(shape_tool.GetLocation_s(label))
            referred = TDF_Label()
            if not shape_tool.GetReferredShape_s(label, referred):
                raise ValueError("Unresolved assembly reference")
        else:
            referred = label
        current = f"{parent}/{name}"
        if shape_tool.IsAssembly_s(referred):
            if current in nodes:
                raise ValueError(f"Duplicate assembly path: {current}")
            nodes[current] = location
            children = TDF_LabelSequence()
            shape_tool.GetComponents_s(referred, children)
            for index in range(1, children.Length() + 1):
                walk(children.Value(index), location, current)

    roots = TDF_LabelSequence()
    shape_tool.GetFreeShapes(roots)
    for index in range(1, roots.Length() + 1):
        walk(roots.Value(index), cq.Location(), "")
    return nodes


def component_name(value: str) -> str:
    return value.replace(" ", "_").replace(":", "_").replace("/", "_")


def rows_below(rows: list, parent: str) -> list:
    return [row for row in rows if row.path.startswith(f"{parent}/")]


def build_prototype(reference_dir: Path = REFERENCE_DIR) -> Prototype:
    baseline = build_geometry(reference_dir)
    rows = baseline.original
    nodes = read_assembly_nodes(reference_dir / "arm.step")
    reference_leaves = rows_below(rows, REFERENCE_XL430)
    if len(reference_leaves) != 35:
        raise ValueError("XL430 reference motor must have 35 leaf occurrences")
    for path in EXISTING_XL430:
        if len(rows_below(rows, path)) != 35:
            raise ValueError(f"Unexpected existing XL430 occurrence: {path}")

    target_rows = {path: rows_below(rows, path) for _, path, _ in TARGETS}
    if any(len(items) != 21 for items in target_rows.values()):
        raise ValueError("A former XL330 occurrence does not have 21 leaves")
    removed = {row.index for items in target_rows.values() for row in items}
    if len(removed) != 84:
        raise ValueError("Replacement targets overlap or are incomplete")

    assembly = cq.Assembly(name="Follower_all_XL430_UNACCEPTED_STUDY")
    manifest = []
    for row in rows:
        if row.index in removed:
            continue
        name = component_name(f"KEEP_{row.index:03d}_{row.name}")
        location = baseline.revised_locations[row.index]
        assembly.add(
            baseline.revised_shapes[row.index],
            loc=location,
            name=name,
            color=row.color or cq.Color(0.68, 0.71, 0.76),
        )
        manifest.append(
            {
                "name": name,
                "source_index": row.index,
                "action": "kept_from_geometry_revision",
                "logical_path": row.path,
                "transform": location.toTuple(),
            }
        )

    placement = baseline.placement
    placement_steps = {
        "distal": cq.Location(tuple(placement["distal_translation_mm"])),
        "wrist": cq.Location(
            tuple(placement["wrist_motor_additional_translation_mm"])
        ),
        "gripper": cq.Location(tuple(placement["gripper_additional_translation_mm"])),
    }
    reference_top = nodes[REFERENCE_XL430]
    for tag, path, transforms in TARGETS:
        target_top = nodes[path]
        for transform in transforms:
            target_top = placement_steps[transform] * target_top
        for index, leaf in enumerate(reference_leaves):
            location = target_top * (reference_top.inverse * leaf.loc)
            name = component_name(f"{tag}_XL430_{index:02d}_{leaf.name}")
            assembly.add(
                leaf.shape,
                loc=location,
                name=name,
                color=leaf.color or cq.Color(0.55, 0.60, 0.66),
            )
            manifest.append(
                {
                    "name": name,
                    "action": "XL330_replaced_with_XL430",
                    "target_occurrence": path,
                    "reference_occurrence": REFERENCE_XL430,
                    "reference_leaf": leaf.path,
                    "logical_path": path + leaf.path[len(REFERENCE_XL430) :],
                    "transform": location.toTuple(),
                }
            )
    if len(manifest) != EXPECTED_LEAVES or len(
        {item["name"] for item in manifest}
    ) != EXPECTED_LEAVES:
        raise ValueError("Invalid replacement manifest")
    return Prototype(assembly, manifest, baseline)


def generate_candidate(run: Path, reference_dir: Path = REFERENCE_DIR) -> None:
    check_reference_hashes()
    if run.exists():
        raise FileExistsError(f"Run already exists; use another run-id: {run.name}")
    prototype = build_prototype(reference_dir)
    parts_dir = run / "CAD/parts"
    parts_dir.mkdir(parents=True)
    prototype.assembly.export(
        str(run / "CAD/arm_all_XL430_static_UNACCEPTED.step")
    )
    mesh_metadata = {}
    for name in PART_NAMES:
        shape = prototype.baseline.parts[name]
        require_single_solid(shape, name)
        cq.exporters.export(shape, str(parts_dir / f"{name}.step"))
        mesh_metadata[name] = export_closed_stl(
            shape,
            parts_dir / f"{name}.stl",
            allow_gripper_repair=name == "gripper_moving_unchanged",
        )
    write_json(run / "replacement_manifest.json", prototype.manifest)
    write_json(run / "reports/baseline_mesh_export.json", mesh_metadata)
    write_json(
        run / "generation.json",
        {
            "study_id": STUDY_ID,
            "acceptance_state": "unaccepted",
            "candidate_kind": "rigid_motor_replacement_no_bracket_redesign",
            "original_leaf_count": 161,
            "removed_leaf_count": 84,
            "inserted_leaf_count": 140,
            "expected_leaf_count": EXPECTED_LEAVES,
            "part_design_status": (
                "mixed_servo_baseline_geometry_not_all_xl430_validated"
            ),
            "reference_sha256": check_reference_hashes(),
        },
    )
    (run / "NOT_FOR_PRINT.txt").write_text(
        "UNACCEPTED / 未承認・印刷禁止\n"
        "全XL430剛体置換の診断用データです。\n"
        "7部品の全XL430適合、静止干渉、連続動作は未合格です。\n",
        encoding="utf-8",
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    args = parser.parse_args(argv)
    try:
        generate_candidate(args.output.resolve())
    except (OSError, RuntimeError, ValueError) as error:
        print(f"FAILED: {error}")
        return 3
    print("Generated unaccepted diagnostic candidate; validation is still required.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

