"""Paths, provenance, and atomic report writes for the diagnostic study."""
from __future__ import annotations
import hashlib
import json
import math
import os
from pathlib import Path
import re
import tempfile
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
STUDY_ID = 'all_xl430_validation_20260919'
EXPECTED_LEAVES = 217
VOLUME_TOLERANCE_MM3 = 1e-4
LENGTH_TOLERANCE_MM = 1e-5
PART_NAMES = (
    'base_idler_clearance', 'shoulder_rotation_unchanged',
    'shoulder_to_elbow_unchanged', 'elbow_to_wrist_extension_round',
    'elbow_to_wrist_standoff', 'gripper_static_unchanged',
    'gripper_moving_unchanged',
)
PENDING_CHECKS = (
    'all_xl430_part_compatibility', 'full_motion_collision', 'holding_torque',
    'strength', 'fasteners_and_assembly', 'physical_fit',
)

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def read_json(path: Path) -> Any:
    def invalid_constant(text: str):
        raise ValueError(f'Non-finite JSON value: {text}')
    with path.open(encoding='utf-8') as stream:
        return json.load(stream, parse_constant=invalid_constant)


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
    handle, temporary = tempfile.mkstemp(dir=path.parent, prefix='.' + path.name)
    try:
        with os.fdopen(handle, 'w', encoding='utf-8') as stream:
            stream.write(data)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def study_run(run_id: str, *, root: Path = ROOT) -> Path:
    """Diagnostic generation cannot be pointed at a release/print directory."""
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]{0,63}', run_id):
        raise ValueError('run-id must be a simple name, not a filesystem path')
    quarantine = root / 'unaccepted'
    if quarantine.is_symlink():
        raise ValueError('unaccepted must not be a symbolic link')
    path = quarantine / run_id
    if path.is_symlink() or path.resolve().parent != quarantine.resolve():
        raise ValueError('Output must remain under unaccepted')
    return path


def check_reference_hashes(*, root: Path = ROOT) -> dict[str, str]:
    expected = read_json(root / 'reference_sha256.json')
    if not isinstance(expected, dict) or not expected:
        raise ValueError('Reference manifest is empty or malformed')
    for relative, value in expected.items():
        path = root / relative
        if path.is_symlink() or not path.resolve().is_relative_to((root / 'reference').resolve()):
            raise ValueError(f'Unsafe reference: {relative}')
        if not path.is_file() or sha256(path) != value:
            raise ValueError(f'Reference missing or changed: {relative}')
    return expected


def candidate_inventory(run: Path) -> dict[str, str]:
    """Bind results to every CAD byte and to the occurrence mapping."""
    paths = [run / 'CAD/arm_all_XL430_static_UNACCEPTED.step',
             run / 'replacement_manifest.json']
    paths += [run / f'CAD/parts/{name}.{ext}' for name in PART_NAMES for ext in ('step', 'stl')]
    expected_parts = {f'{name}.{ext}' for name in PART_NAMES for ext in ('step', 'stl')}
    part_directory = run / 'CAD/parts'
    if not part_directory.is_dir() or {p.name for p in part_directory.iterdir()} != expected_parts:
        raise ValueError('Unexpected, missing or extra files in candidate parts directory')
    inventory = {}
    for path in paths:
        if path.is_symlink() or not path.resolve().is_relative_to(run.resolve()) or not path.is_file():
            raise ValueError(f'Candidate input absent or unsafe: {path.name}')
