from __future__ import annotations
import hashlib
import json
import math
import os
from pathlib import Path
import re
import tempfile
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
STUDY_ID = 'all_xl430_validation_20260919'
EXPECTED_LEAVES = 217
VOLUME_TOLERANCE_MM3 = 1e-4
