            raise ValueError(f'Unsafe reference: {relative}')
        if not path.is_file() or sha256(path) != value:
            raise ValueError(f'Reference missing or changed: {relative}')
    return expected


def candidate_inventory(run: Path) -> dict[str, str]:
    """Bind results to every CAD byte and to the occurrence mapping."""
    paths = [run / 'CAD/arm_all_XL430_static_UNACCEPTED.step',
