import itertools, json

GAP = 9.0
MARGIN = 5.0
BED = 220.0
W = BED - 2*MARGIN

parts = {
    'P01_base':                (133.0, 80.0, 9.0),
    'P02_yaw_carrier':         (40.0, 52.5, 10.9),
    'P03_shoulder_XL430':      (44.0, 46.5, 107.1),
    'P04_extension_XL430':     (46.0, 114.8, 31.7),
    'P05_wrist_XL430':         (46.0, 83.5, 45.5),
    'P06_fixed_gripper_XL430': (40.0, 121.0, 31.7),
    'P07_moving_gripper_XL430':(27.0, 83.5, 16.0),
}

def maxrects(rects):
    # rects: list of (name, w, h) ; returns placements name->(x,y,w,h) or None
    free = [(0.0, 0.0, W, W)]
    placed = {}
    for name, w, h in sorted(rects, key=lambda r: max(r[1], r[2]), reverse=True):
        best = None
        for (fx, fy, fw, fh) in free:
            for (pw, ph) in ((w, h), (h, w)):
                if pw <= fw + 1e-9 and ph <= fh + 1e-9:
                    short = min(fw - pw, fh - ph)
                    long_ = max(fw - pw, fh - ph)
                    if best is None or (short, long_) < best[0]:
                        best = ((short, long_), fx, fy, pw, ph, fw, fh)
        if best is None:
            return None
        _, fx, fy, pw, ph, fw, fh = best
        placed[name] = (fx, fy, pw, ph)
        new_free = []
        for (rx, ry, rw, rh) in free:
            if rx >= fx + pw - 1e-9 or rx + rw <= fx + 1e-9 or ry >= fy + ph - 1e-9 or ry + rh <= fy + 1e-9:
                new_free.append((rx, ry, rw, rh))
                continue
            if fx > rx: new_free.append((rx, ry, fx - rx, rh))
            if fx + pw < rx + rw: new_free.append((fx + pw, ry, rx + rw - fx - pw, rh))
            if fy > ry: new_free.append((rx, ry, rw, fy - ry))
            if fy + ph < ry + rh: new_free.append((rx, fy + ph, rw, ry + rh - fy - ph))
        # prune contained
        pruned = []
        for r in new_free:
            if any(r is not s and s[0] <= r[0]+1e-9 and s[1] <= r[1]+1e-9 and s[0]+s[2] >= r[0]+r[2]-1e-9 and s[1]+s[3] >= r[1]+r[3]-1e-9 for s in new_free):
                continue
            pruned.append(r)
        free = pruned
    return placed

rects = [(n, w + GAP, h + GAP) for n, (w, h, z) in parts.items()]
result = maxrects(rects)
if result is None:
    print('NO PACKING'); raise SystemExit(1)
layout = {}
for name, (x, y, pw, ph) in result.items():
    w, h, z = parts[name]
    layout[name] = {'x': round(x + MARGIN, 1), 'y': round(y + MARGIN, 1), 'w': w, 'h': h, 'h_rot': pw != w, 'z': z}
    print(f"{name:28s} at ({x+MARGIN:6.1f},{y+MARGIN:6.1f}) size {w}x{h} rot={pw!=w} -> ends ({x+MARGIN+w:6.1f},{y+MARGIN+h:6.1f})")
# verify no overlap with actual sizes + gap
names = list(layout)
ok = True
for a, b in itertools.combinations(names, 2):
    A, B = layout[a], layout[b]
    gx = max(A['x'] + A['w'], B['x'] + B['w']) - min(A['x'], B['x']) - A['w'] - B['w']
    gy = max(A['y'] + A['h'], B['y'] + B['h']) - min(A['y'], B['y']) - A['h'] - B['h']
    if gx < 0 and gy < 0:
        print('OVERLAP', a, b); ok = False
    elif (gx if gx >= 0 else 1e9) < 0 or True:
        pass
mins = []
for a, b in itertools.combinations(names, 2):
    A, B = layout[a], layout[b]
    dx = max(0.0, max(A['x'], B['x']) - min(A['x']+A['w'], B['x']+B['w']))
    dy = max(0.0, max(A['y'], B['y']) - min(A['y']+A['h'], B['y']+B['h']))
    mins.append((round(dx if dx > 0 else dy, 2), a, b))
print('min separation:', sorted(mins)[:3])
print('packing valid:', ok)
json.dump(layout, open('packed_layout.json', 'w'), indent=2)
EOF
