            pw += gap; ph += gap
            for i in range(len(sky)):
                x = sky[i][0]
                if x + pw > W + 1e-9: continue
                y = 0.0; j = i; width = 0.0
                while j < len(sky) and width < pw - 1e-9:
                    y = max(y, sky[j][2]); width += sky[j][1]; j += 1
                if width < pw - 1e-9: continue
                cand = (y + ph, y, x)
                if best is None or cand < best[0]:
                    best = (cand, x, y, pw, ph, rot)
        if best is None: return None
        _, x, y, pw, ph, rot = best
        placed[name] = (x, y, pw - gap, ph - gap, rot)
        new_sky = []
        for (sx, sw, sy) in sky:
            if sx + sw <= x + 1e-9 or sx >= x + pw - 1e-9:
                new_sky.append((sx, sw, sy)); continue
            if sx < x: new_sky.append((sx, x - sx, sy))
            if sx + sw > x + pw: new_sky.append((x + pw, sx + sw - x - pw, sy))
        new_sky.append((x, pw, y + ph))
        new_sky.sort()
        # merge adjacent equal-height segments
        merged = []
        for seg in new_sky:
            if merged and abs(merged[-1][2] - seg[2]) < 1e-9 and abs(merged[-1][0] + merged[-1][1] - seg[0]) < 1e-9:
                merged[-1] = (merged[-1][0], merged[-1][1] + seg[1], merged[-1][2])
            else:
                merged.append(seg)
        sky = merged
    return placed

def try_pack(margin, gap):
    W = 220.0 - 2*margin
    names = list(parts)
    orderings = sorted(itertools.permutations(names), key=lambda o: sum(parts[n][0]*parts[n][1] for n in o), reverse=True)
    for order in orderings:
        placed = skyline_pack(order, parts, W, gap)
        if placed is None: continue
        max_y = max(y + h for (x, y, w, h, rot) in placed.values())
        if max_y > W + 1e-9: continue
        layout = {}
        for n, (x, y, w, h, rot) in placed.items():
            layout[n] = {'x': round(x + margin, 1), 'y': round(y + margin, 1), 'w': w, 'h': h, 'rot': rot}
        return layout
    return None

for margin, gap in ((5, 9), (4, 8), (3, 8), (3, 7)):
    layout = try_pack(margin, gap)
    print(f'margin={margin} gap={gap} ->', 'OK' if layout else 'no packing')
    if layout:
        for n in sorted(layout, key=lambda k: (layout[k]['y'], layout[k]['x'])):
            L = layout[n]
            print(f"  {n:28s} ({L['x']:6.1f},{L['y']:6.1f}) {L['w']:6.1f}x{L['h']:6.1f} rot={L['rot']} end=({L['x']+L['w']:.1f},{L['y']+L['h']:.1f})")
        # min separation check
        import itertools as it
        mind = 1e9; pair=None
        for a, b in it.combinations(layout, 2):
            A, B = layout[a], layout[b]
            dx = max(0.0, max(A['x'], B['x']) - min(A['x']+A['w'], B['x']+B['w']))
            dy = max(0.0, max(A['y'], B['y']) - min(A['y']+A['h'], B['y']+B['h']))
            d = math.hypot(dx, dy) if dx > 0 or dy > 0 else -1
            if d < mind: mind = d; pair=(a,b)
        print('  min gap:', round(mind,2), pair)
        json.dump({'margin': margin, 'gap': gap, 'layout': layout}, open('packed_layout.json','w'), indent=2)
        break
